"""Workspace-relative file reading and exact local editing operations."""

from infrastructure.shared.agent.files import EXCLUDED
from infrastructure.utils.files import normalize_newlines, read_source
from infrastructure.utils.paths import check_path_case, relative_path


class FileToolError(ValueError):
    def __init__(self, code, message, path=None, **details):
        super().__init__(message)
        self.feedback = {"code": code, "message": message, **details}
        if path is not None:
            self.feedback["path"] = path


def workspace_path(root, path):
    """Translate a portable model path into a native path inside the project."""
    parts = relative_path(path).parts
    if any(part.startswith(".") or part in EXCLUDED for part in parts) or parts[:2] == ("backend", "data"):
        raise FileToolError("INVALID_PATH", "Use a project source/configuration path", path)
    check_path_case(root, path)
    current = root
    for part in parts:
        current = current / part
        if current.is_symlink():
            raise FileToolError("INVALID_PATH", "Symlinks are not allowed", path)
    if not current.resolve().is_relative_to(root.resolve()) or current.is_dir():
        raise FileToolError("INVALID_PATH", "Use a file inside the working directory", path)
    return current


def read_file(files, path, start_line=1, end_line=None):
    """Read the requested lines only; reading never expands the pinned source context."""
    target = files.path(path)
    if files.readable is not None and path not in files.readable:
        raise FileToolError("READ_NOT_ALLOWED", "This task cannot read this file", path)
    if not target.is_file():
        # A miss is information, not a failed round: models often guess conventional
        # filenames (playwright.config.ts) that this project never created. Return the
        # observation so the same round can continue with the paths it does have.
        return {"path": path, "exists": False, "content": None, "start_line": 1, "end_line": 0,
            "total_lines": 0, "writable": files.can_write(path),
            "notice": "This file does not exist. Read an existing path, or use edit_file operation=create to add it."}
    if type(start_line) is not int or start_line < 1 or (end_line is not None and
            (type(end_line) is not int or end_line < start_line)):
        raise FileToolError("INVALID_LINE_RANGE", "Use positive, inclusive line numbers", path)
    lines = read_source(target).splitlines(keepends=True)
    last = min(end_line if end_line is not None else len(lines), len(lines))
    return {"path": path, "content": "".join(lines[start_line - 1:last]), "start_line": start_line,
        "end_line": last, "total_lines": len(lines), "writable": files.can_write(path)}


def edit_file(files, path, operation, new_content, old_content=""):
    """Stage a create, unique exact replacement, prepend or append in the current batch."""
    files.path(path)  # Reject unsafe paths before attempting task-specific adaptation.
    requested = path
    if files.pending_target and files._target_path is None:
        if operation == "create":
            path = files.target.adapt(path)
            files.path(path)
            files._target_path = path
        elif files.can_write(path) and path.startswith(files.target.directory + "/"):
            # A page or API is often implemented inside an existing shared module, so the
            # first writable source edit claims that file as this task's target instead of
            # demanding a brand-new file (which would reject every incremental edit).
            # Page targets prefer component files: shared .ts stores must not claim a page.
            if files.target.kind == "page":
                claims = path.endswith(".tsx") or "/pages/" in path
            else:
                claims = path.endswith((".ts", ".tsx"))
            if claims:
                files._target_path = path
    if not files.can_write(path) and path != files._target_path:
        raise FileToolError("WRITE_NOT_ALLOWED", "File is not writable for this task", path)
    if not isinstance(new_content, str) or not isinstance(old_content, str):
        raise FileToolError("INVALID_ARGUMENTS", "old_content and new_content must be strings", path)
    new_content, old_content = normalize_newlines(new_content), normalize_newlines(old_content)
    target = files.path(path)
    current = files._pending.get(path, read_source(target) if target.is_file() else None)
    if operation == "create":
        if current is not None:
            raise FileToolError("FILE_ALREADY_EXISTS", "Read the existing file and use replace", path)
        if old_content:
            raise FileToolError("INVALID_ARGUMENTS", "create requires empty old_content", path)
        updated = new_content
    elif operation in {"replace", "prepend", "append"}:
        if current is None:
            raise FileToolError("FILE_NOT_FOUND", "Use create for a missing file", path)
        if operation == "replace":
            if not old_content:
                raise FileToolError("INVALID_ARGUMENTS", "replace requires nonempty exact old_content", path)
            if current.strip() and old_content.strip() == current.strip():
                raise FileToolError("WHOLE_FILE_REPLACEMENT_NOT_ALLOWED",
                    "Incremental compilation forbids replacing a whole existing file. "
                    "Use a smaller unique span and preserve earlier requirements, registrations and state.", path)
            first = current.find(old_content)
            count = 0 if first < 0 else (2 if current.find(old_content, first + 1) >= 0 else 1)
            if count != 1:
                raise FileToolError("OLD_CONTENT_NOT_FOUND" if count == 0 else "OLD_CONTENT_NOT_UNIQUE",
                    f"Expected exactly one old_content match, found {count}; read the relevant lines and retry", path)
            updated = current.replace(old_content, new_content, 1)
        else:
            if old_content:
                raise FileToolError("INVALID_ARGUMENTS", "Boundary insertion requires empty old_content", path)
            updated = new_content + current if operation == "prepend" else current + new_content
    else:
        raise FileToolError("INVALID_OPERATION", "Use create, replace, prepend or append", path)
    files._pending[path] = updated
    result = {"path": path, "operation": operation}
    if path != requested:
        result["requested_path"] = requested
        result["notice"] = "Adapted to this task's required destination; use path in future calls and imports"
    return result

"""Bounded, on-demand access to compiler-owned global state."""

import json
from copy import deepcopy

from infrastructure.shared.agent.files import source_paths
from infrastructure.shared.rag.bm25 import tokenize
from infrastructure.utils.files import read_artifact

DISCOVERY_RULES = '''Context contains selected excerpts, never a complete global inventory.
Use the supplied task records first. Query only a specific missing fact needed for the
current decision; do not search to reconfirm definitions already supplied or retained.
When evidence is missing, return only {"context_request": {"kind": "schema",
"query": "session credential"}} to discover candidates, or use "ids": ["Account.id"]
to read exact records. Available kinds are listed in context_kinds.
context_request is an ordinary JSON field, NOT a native tool. Never serialize it as
DSML, XML, invoke/parameter tags or a provider tool-call block. For example, when page
is an advertised kind, search shelves by returning exactly:
{"context_request":{"kind":"page","query":"shelves"}}
Do not put this object inside tags, Markdown or a JSON string.
Only those advertised kinds are supported; examples below do not enable other scopes.
Search returns IDs/descriptions, not definitions, except requirement searches return complete records.
Read needed IDs before modifying or calling other kinds of records.
Each query searches only its named kind; do not search unrelated collections for context.
Use offset to inspect another search page. A miss is not proof of absence. Search
shared concepts before creating new entities/APIs; reuse canonical definitions.
For schema, read Entity.field for a narrow field definition; for large pages read
ui_element IDs. kind=file supports exact relative paths or keyword discovery.
For a file excerpt, supply "start_line": 10 and "end_line": 40 alongside ids.
Lines are 1-based and inclusive; end_line may be omitted to read through EOF.
Excerpts return content, start_line, end_line and total_lines. File-writing agents use
read_file instead of kind=file exact reads; semantic design tasks may use these excerpts.
kind=requirement reads original requirement scenarios; kind=test_requirement with a
test file path as an ID finds its original requirement owner IDs. Read the relevant requirement before
changing a regression test; never infer its intended behavior from implementation.
Exact records are retained in context_records and search candidates in context_candidates
for the current task. File-editing tasks
also retain read_file excerpts in read_files. Use retained evidence instead of querying
it again. Return your normal stage output when enough evidence is available.
There is no fixed query-count or character cap. Prefer exact reads after candidate
searches. Do not repeat searches returning the same candidates: read their IDs, or
produce the stage output using the available evidence. Query errors are feedback,
not evidence that an object is absent.'''


class DiscoveryStalled(ValueError):
    """Repeated identical results need a proposal or different evidence, not more searches."""


class DiscoverySession:
    """Allow as many useful queries as needed; return malformed queries as feedback."""

    def __init__(self, index):
        self.index = index
        self.results = {}
        self.evidence = {}
        self.candidates = {}

    def resolve(self, query):
        try:
            result = self.index.query(query)
        except (ValueError, KeyError, TypeError, AttributeError, IndexError) as error:
            raise ValueError(f'Invalid context_request {query!r}: {error}. '
                f'Available kinds: {list(self.index.records())}. '
                'Correct the query or return the normal stage output.') from error
        kind = result.get('kind')
        for candidate in result.get('candidates', []):
            if candidate['id'] not in self.evidence.get(kind, {}):
                self.candidates.setdefault(kind, {})[candidate['id']] = deepcopy(candidate)
        if result.get('records'):
            self.evidence.setdefault(kind, {}).update(deepcopy(result['records']))
            for identity in result['records']:
                self.candidates.get(kind, {}).pop(identity, None)
        return self.observe(result)

    def observe(self, result):
        """Apply the same no-progress feedback to semantic queries and file reads."""
        fingerprint = json.dumps(result, sort_keys=True, ensure_ascii=False)
        count = self.results.get(fingerprint, 0) + 1
        self.results[fingerprint] = count
        if count >= 3:
            raise DiscoveryStalled('Discovery returned the same evidence repeatedly. '
                'Read different relevant evidence or return the task output.')
        if count == 2:
            result = {**result, 'next_action': 'These results were already supplied. '
                'Read different evidence or produce the task output.'}
        return result



class ContextIndex:
    """Keep complete collections in the host; expose small candidate pages and exact reads."""
    def __init__(self, collections, output=None):
        self.collections = collections
        self.output = output

    def records(self):
        return self.collections() if callable(self.collections) else self.collections

    def query(self, request):
        collections = self.records()
        kind = request['kind']
        records = collections[kind]
        ids = request.get('ids')
        ranged = 'start_line' in request or 'end_line' in request
        if ranged:
            if kind != 'file' or ids is None:
                raise ValueError('Line ranges require kind=file and exact ids')
            start, end = request.get('start_line', 1), request.get('end_line')
            if type(start) is not int or start < 1 or ('end_line' in request and
                    (type(end) is not int or end < start)):
                raise ValueError('Line numbers must be positive integers with end_line >= start_line')
        if ids is not None:
            if not isinstance(ids, list) or any(not isinstance(identity, str) for identity in ids):
                raise ValueError('ids must be an array of strings')
            found = {}
            for identity in ids:
                if kind == 'file':
                    if identity not in records:
                        continue
                    path = self.output / identity
                    if path.is_symlink() or not path.resolve().is_relative_to(self.output.resolve()):
                        raise ValueError('File must be inside the project')
                    content = path.read_text(encoding='utf-8-sig')
                    if ranged:
                        lines = content.splitlines(keepends=True)
                        last = min(end if end is not None else len(lines), len(lines))
                        found[identity] = {'content': ''.join(lines[start - 1:last]),
                            'start_line': start, 'end_line': last, 'total_lines': len(lines)}
                    else:
                        found[identity] = content
                elif kind == 'schema' and '.' in identity:
                    entity, field = identity.split('.', 1)
                    if entity in records and field in records[entity]['fields']:
                        found[identity] = records[entity]['fields'][field]
                elif identity in records:
                    if kind == 'test_requirement':
                        offset = max(0, int(request.get('offset', 0)))
                        owners = records[identity]
                        found[identity] = {'requirement_ids': owners[offset:offset + 6],
                            'next_offset': offset + 6 if offset + 6 < len(owners) else None}
                    else:
                        found[identity] = records[identity]
            result = {'records': deepcopy(found), 'missing': [key for key in ids if key not in found]}
        else:
            words = set(tokenize(request['query']))
            if not words:
                raise ValueError('Provide a nonempty discovery query')
            scores = []
            for key, record in records.items():
                text = key + ' ' + json.dumps(record, ensure_ascii=False)
                score = len(words.intersection(tokenize(text)))
                if request['query'].lower() in text.lower():
                    score += 1
                if score:
                    scores.append((-score, key))
            scores.sort()
            offset = max(0, int(request.get('offset', 0)))
            candidates = []
            for _, key in scores[offset:offset + 6]:
                value = records[key]
                description = value.get('description', value.get('name', '')) if isinstance(value, dict) else ''
                candidates.append({'id': key, 'description': str(description)[:300]})
            result = {'candidates': candidates, 'next_offset': offset + 6 if offset + 6 < len(scores) else None,
                'notice': 'Lexical candidates only. A miss does not establish absence.'}
            if kind == 'requirement':
                result['records'] = {item['id']: deepcopy(records[item['id']]) for item in candidates}
                del result['candidates']
        return {'kind': kind, **result}


def project_index(output, *, kinds, file_roots=()):
    """Expose only stage-selected collections and source directories, rebuilt on demand."""
    from infrastructure.stages.requirements.tree import RequirementTree
    from infrastructure.stages.backend.context import requirement_context
    from infrastructure.stages.frontend.ui.design import owners, data_symbols

    def artifact(name, default):
        return read_artifact(output / '.arc', name) if (output / '.arc' / name).is_file() else default

    def records():
        result = {}
        backend_tests = 'test_requirement' in kinds and any(root.startswith('backend/') for root in file_roots)
        frontend_tests = 'test_requirement' in kinds and any(root.startswith('frontend/') for root in file_roots)
        if 'schema' in kinds:
            result['schema'] = artifact('db_schema.json', {'entities': {}})['entities']
        if 'api' in kinds or backend_tests:
            backend = artifact('backend_apis.json', {'apis': {}, 'requirements': {}})
            if 'api' in kinds:
                result['api'] = backend['apis']
        if any(kind in kinds for kind in ('page', 'ui_element', 'ui_data')) or frontend_tests:
            ui = artifact('ui_design.json', {'pages': {}, 'elements': {}, 'requirements': {}})
            if 'page' in kinds:
                result['page'] = ui['pages']
            if 'ui_element' in kinds:
                result['ui_element'] = ui['elements']
            if 'ui_data' in kinds:
                result['ui_data'] = data_symbols(ui['elements'])
        if 'trigger' in kinds:
            result['trigger'] = artifact('frontend_triggers.json', {'triggers': {}})['triggers']
        if 'convention' in kinds:
            result['convention'] = artifact('shared_conventions.json', {})
        if 'requirement' in kinds or 'test_requirement' in kinds:
            tree = RequirementTree(artifact('requirements.json', {'id': 'ROOT'}))
            requirements = {rid: requirement_context(tree, rid) for rid in tree.leaves}
            if 'requirement' in kinds:
                result['requirement'] = requirements
        if 'test_requirement' in kinds:
            paths = artifact('implementation_paths.json', {})
            test_owners = {}
            if backend_tests:
                for aid, path in paths.get('backend_test', {}).items():
                    test_owners[path] = [rid for rid, aids in backend['requirements'].items()
                        if aid in aids and rid in requirements]
            if frontend_tests:
                for rid, path in paths.get('e2e_test', {}).items():
                    test_owners[path] = [rid] if rid in requirements else []
                for pid in ui['pages']:
                    path = f'frontend/tests/ui/{pid}.spec.ts'
                    test_owners[path] = [rid for rid in owners(ui, pid) if rid in requirements]
            prefixes = tuple(root + '/' for root in file_roots)
            result['test_requirement'] = {path: ids for path, ids in test_owners.items()
                if path.startswith(prefixes)}
        if 'file' in kinds:
            result['file'] = {path: {} for root in file_roots for path in source_paths(output, root)}
        return result

    return ContextIndex(records, output)

"""Full SDK and HTTP model I/O audit, with concise progress on the terminal."""

from datetime import datetime, timezone
import json
import re
import traceback
from time import monotonic
from uuid import uuid4
from contextvars import ContextVar

import httpx

from infrastructure.utils.presentation.console import current_activity, preview, show_panel, WaitingStatus
from infrastructure.utils.presentation.logging import session_info, full_detail
from rich.console import Group
from rich.panel import Panel
from rich.syntax import Syntax
from rich.text import Text
from infrastructure.utils.presentation.artifacts import proposal_kind, render_artifact, table, text


_call = ContextVar("compiler_model_call", default=None)


def _exception_chain(error: BaseException) -> list[dict[str, str]]:
    """Return every linked exception without losing explicit or implicit context."""
    chain = []
    seen = set()
    current = error
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        chain.append({"type": type(current).__name__, "message": str(current)})
        # Explicit ``raise ... from ...`` takes precedence over implicit context.
        current = current.__cause__ or (None if current.__suppress_context__ else current.__context__)
    return chain


def _record(event: str, **data) -> None:
    """Append untruncated values; never record authentication headers."""
    call = _call.get()
    session = session_info()
    if not session or not session.get("model_log", True):
        return
    record = {"timestamp": datetime.now(timezone.utc).isoformat(),
        "stage": session["stage"], "call_id": call["id"] if call else None,
        "activity": call["activity"] if call else current_activity(), "event": event, **data}
    with session["lock"]:
        with (session["output"] / "model_calls.jsonl").open("a", encoding="utf-8", newline="\n") as log:
            log.write(json.dumps(record, ensure_ascii=False) + "\n")


def _message_text(message: dict) -> str:
    """Return message text verbatim, without the transport JSON envelope."""
    content = message.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(part["text"] for part in content if part.get("type") == "text")
    return ""


def _http_request(request: httpx.Request) -> None:
    """Capture the actual serialized body on every HTTP attempt, including retries."""
    session, call = session_info(), _call.get()
    if session and session.get("debug_model_io") and call:
        call["attempt"] = call.get("attempt", 0) + 1
        stage = session["stage"].split(" | ", 1)[0].removeprefix("Stage ")
        task = re.sub(r"[^\w.-]+", "_", call["activity"].split(" | ", 1)[0]).strip("._")[:24] or "model"
        directory = session["output"] / ".arc" / "model_logs"
        directory.mkdir(parents=True, exist_ok=True)
        prefix = directory / f"{stage.replace(' ', '_')}.{task}.{call['id'][:8]}.{call['attempt']}"
        request.extensions["compiler_model_log_prefix"] = prefix
        messages = json.loads(request.content).get("messages", [])
        text = "\n\n".join(_message_text(message) for message in messages)
        prefix.with_name(prefix.name + ".model.input").write_text(text, encoding="utf-8", newline="\n")
    _record("http_request", method=request.method, url=str(request.url.copy_with(query=None)),
        body=request.content.decode("utf-8"))


def _http_response(response: httpx.Response) -> None:
    """Read and retain the complete non-streaming response before SDK parsing."""
    response.read()
    prefix = response.request.extensions.get("compiler_model_log_prefix")
    if prefix is not None:
        try:
            body = response.json()
        except ValueError:
            text = response.text
        else:
            if isinstance(body, dict) and "choices" in body:
                text = "\n\n".join(_message_text(choice.get("message", {})) for choice in body["choices"])
            elif isinstance(body, dict) and isinstance(body.get("error"), dict):
                text = str(body["error"].get("message", ""))
            else:
                text = response.text
        prefix.with_name(prefix.name + ".model.ouput").write_text(text, encoding="utf-8", newline="\n")
    _record("http_response", status_code=response.status_code,
        request_id=response.headers.get("x-request-id"), body=response.text)


def http_client() -> httpx.Client:
    """Connect directly, retaining audit hooks and the SDK's transport limits."""
    from openai import DefaultHttpxClient
    return DefaultHttpxClient(trust_env=False, timeout=httpx.Timeout(600),
        event_hooks={"request": [_http_request], "response": [_http_response]})


def _input_summary(arguments: dict) -> str:
    messages = arguments.get("messages", [])
    lines = [f"Model: {arguments.get('model')} | Messages: {len(messages)}"]
    for message in messages:
        content = message.get("content", "")
        if isinstance(content, str):
            line = str(message["role"])
            if message["role"] == "user":
                try:
                    payload = json.loads(content)
                except ValueError:
                    payload = None
                if isinstance(payload, dict):
                    line += " | sections: " + ", ".join(payload)
                    files = payload.get("files")
                    if isinstance(files, dict):
                        writable = sum(bool(item.get("writable")) for item in files.values() if isinstance(item, dict))
                        line += f" | files: {len(files)} ({writable} writable)"
            lines.append(line)
        else:
            images = sum(part.get("type") == "image_url" for part in content)
            lines.append(f"{message['role']}: text and images | images: {images}")
    return "\n".join(lines)


def _usage_summary(usage: dict) -> str:
    """Keep a compact plain-text usage line in the persistent log."""
    counts = _usage_counts(usage)
    summary = "Reported tokens | " + " | ".join(
        f"{name.lower()}: {counts[name]:,}" if counts[name] is not None else f"{name.lower()}: unavailable"
        for name in ("Input", "Cached input", "Output", "Total"))
    if counts["Reasoning"] is not None:
        summary += f"\nReasoning tokens: {counts['Reasoning']:,} | Non-reasoning output: {counts['Non-reasoning output']}"
    return summary


def _input_view(arguments):
    """Show bounded literal prompts and a file access inventory, excluding image data."""
    views = [Text(_input_summary(arguments))]
    for message in arguments.get("messages", [])[:6]:
        prompt = _message_text(message)
        views.append(Panel(Text(preview(prompt, max_lines=10, max_chars=1000)),
            title=Text(str(message.get("role", "message"))), border_style="dim blue"))
        if message.get("role") == "user":
            try:
                payload = json.loads(prompt)
            except ValueError:
                payload = None
            if isinstance(payload, dict) and isinstance(payload.get("files"), dict):
                files = table("File", "Access")
                for path, record in list(payload["files"].items())[:16]:
                    files.add_row(text(path), text("edit" if isinstance(record, dict) and record.get("writable") else "read"))
                views.append(files)
    return Group(*views)


def _usage_counts(usage):
    """Normalize provider aliases, retaining unknown values and reported zeroes."""
    def first(*values):
        return next((value for value in values if type(value) is int), None)
    details = usage.get("prompt_tokens_details") or usage.get("input_tokens_details") or {}
    output = first(usage.get("completion_tokens"), usage.get("output_tokens"))
    reasoning = first((usage.get("completion_tokens_details") or {}).get("reasoning_tokens"))
    return {"Input": first(usage.get("prompt_tokens"), usage.get("input_tokens")),
        "Cached input": first(details.get("cached_tokens"), usage.get("prompt_cache_hit_tokens")),
        "Output": output, "Reasoning": reasoning,
        "Non-reasoning output": output - reasoning if output is not None and reasoning is not None else None,
        "Total": first(usage.get("total_tokens"))}


def _output_view(content, usage, elapsed):
    """Rendering an incomplete proposal must not change the model call outcome."""
    try:
        return _structured_output_view(content, usage, elapsed)
    except (ValueError, TypeError, KeyError, AttributeError, RecursionError):
        return Group(Text(_usage_summary(usage)), Text(f"Round-trip latency: {elapsed:.2f} s"), Text(preview(content)))


def _usage_view(usage, elapsed):
    """Usage and timing remain visible even when detailed model logging is off."""
    metrics = table("Usage / timing", "Reported value")
    for name, value in _usage_counts(usage).items():
        metrics.add_row(text(name), text(f"{value:,}" if value is not None else "unavailable"))
    metrics.add_row(text("Round-trip latency"), Text(f"{elapsed:.2f} s", style="bold cyan"))
    return metrics


def _structured_output_view(content, usage, elapsed):
    views = [_usage_view(usage, elapsed), Text("Model proposal · acceptance belongs to the current compiler pass", style="dim")]
    try:
        value = json.loads(content)
    except ValueError:
        value = None
    if isinstance(value, dict) and isinstance(value.get("tool_calls"), list):
        calls = table("File tool", "Path", "Operation / lines")
        for call in value["tool_calls"][:16]:
            if not isinstance(call, dict):
                continue
            detail = call.get("operation", f"{call.get('start_line', 1)}..{call.get('end_line', 'EOF')}")
            calls.add_row(text(call.get("tool", "?")), text(call.get("path", "?")), text(detail))
        views.append(calls)
    elif isinstance(value, dict) and isinstance(value.get("edits"), list):
        edits = table("File edits", "Source lines")
        for edit in value["edits"][:16]:
            if isinstance(edit, dict):
                edits.add_row(text(edit.get("path", "?")), text(len(str(edit.get("content", "")).splitlines())))
        views.append(edits)
        for edit in value["edits"][:2]:
            if not isinstance(edit, dict) or not isinstance(edit.get("content"), str):
                continue
            path = str(edit.get("path", ""))
            extension = path.rsplit(".", 1)[-1]
            lexer = {"ts": "typescript", "tsx": "tsx", "js": "javascript", "py": "python", "sql": "sql", "json": "json"}.get(extension, "text")
            views.append(Panel(Syntax(preview(edit["content"], max_lines=10, max_chars=1200), lexer,
                theme="ansi_dark", word_wrap=True, background_color="default"), title=text(path), border_style="dim"))
    elif isinstance(value, dict) and isinstance(value.get("content"), str):
        path = str(value.get("path", "SQL proposal"))
        views.append(Panel(Syntax(preview(value["content"], max_lines=16, max_chars=1800), "sql",
            theme="ansi_dark", word_wrap=True, background_color="default"), title=text(path), border_style="dim"))
    elif isinstance(value, dict) and isinstance(value.get("contract"), dict):
        contract = table("Condition", "Description")
        for key in ("precondition", "postcondition"):
            for item in value["contract"].get(key, [])[:12]:
                contract.add_row(text(key), text(item.get("description", item) if isinstance(item, dict) else item, 600))
        views.append(contract)
    elif isinstance(value, dict):
        try:
            views.append(render_artifact(proposal_kind(value), value, context=(session_info() or {}).get("artifacts", {})))
        except (ValueError, TypeError, KeyError, AttributeError, RecursionError):
            views.append(Text(preview(content)))
    else:
        views.append(Text(preview(content)))
    return Group(*views)


def _count_call(usage, elapsed, failed=False):
    session = session_info()
    if session is None:
        return
    stats = session.setdefault("model_stats", {})
    stats["calls"] = stats.get("calls", 0) + 1
    stats["failed"] = stats.get("failed", 0) + int(failed)
    stats["seconds"] = stats.get("seconds", 0) + elapsed
    for key, value in _usage_counts(usage).items():
        if value is not None:
            stats[key] = stats.get(key, 0) + value
            stats[key + " reports"] = stats.get(key + " reports", 0) + 1


def show_call_totals():
    """Summarize this stage's SDK calls; cached input is a subset of input."""
    stats = (session_info() or {}).get("model_stats", {})
    if not stats:
        return
    view = table("Stage model calls", "Value", "Usage availability")
    view.add_row(text("Calls / failed"), text(f"{stats['calls']} / {stats['failed']}"), text("SDK calls; time includes retries"))
    view.add_row(text("Total round-trip time"), text(f"{stats['seconds']:.2f} s"), text("sum of calls"))
    for key in ("Input", "Cached input", "Output", "Reasoning", "Non-reasoning output", "Total"):
        view.add_row(text(key), text(f"{stats[key]:,}" if key in stats else "unavailable"),
            text(f"reported in {stats.get(key + ' reports', 0)}/{stats['calls']} calls"))
    show_panel("Stage model usage | reported counts only", view, tone="output")


def invoke(client, arguments: dict):
    """Audit one SDK call and show a static waiting message until it returns."""
    call_id = uuid4().hex
    activity = current_activity()
    session = session_info()
    label = f"{session['stage']} | {activity}" if session else activity
    token = _call.set({"id": call_id, "activity": activity})
    verbose = session is None or session.get("model_log", True)
    if verbose:
        full_detail(f"[MODEL INPUT] {label}", "\n\n".join(_message_text(message) for message in arguments.get("messages", [])))
        show_panel(f"[MODEL INPUT] {label} | call {call_id[:8]}", _input_view(arguments), tone="input")
    else:
        show_panel(f"[MODEL CALL] {label} | call {call_id[:8]}", f"Model: {arguments.get('model')}", tone="input")
    waiting = WaitingStatus()
    started = monotonic()

    try:
        _record("request", arguments=arguments)
        started = monotonic()
        response = client.chat.completions.create(**arguments)
        elapsed = monotonic() - started
        # Preserve the SDK envelope and untouched message content before any JSON repair.
        raw = response.model_dump(mode="json")
        _record("response", elapsed_seconds=elapsed, response=raw)
        waiting.close()
        content = "\n".join(choice.message.content or "" for choice in response.choices)
        usage = raw.get("usage") or {}
        _count_call(usage, elapsed)
        full_detail(f"[MODEL OUTPUT] {label}", _usage_summary(usage) + f"\nRound-trip latency: {elapsed:.2f} s" + ("\n" + content if verbose else ""))
        show_panel(f"[MODEL OUTPUT] {label} | {elapsed:.2f}s",
            _output_view(content, usage, elapsed) if verbose else _usage_view(usage, elapsed), tone="output")
        return response
    except BaseException as error:
        elapsed = monotonic() - started
        _count_call({}, elapsed, failed=True)
        waiting.close()
        chain = _exception_chain(error)
        cause = ": ".join(f"{item['type']}: {item['message']}" for item in chain[1:]) or None
        _record("error", elapsed_seconds=elapsed,
            error_type=type(error).__name__, message=str(error), cause=cause,
            exception_chain=chain,
            traceback="".join(traceback.format_exception(error)))
        detail = f"Round-trip latency: {elapsed:.2f} s\n{type(error).__name__}: {error}"
        if cause:
            detail += "\nCause: " + cause
        show_panel(f"[MODEL FAILED] {label}", detail, tone="error", max_lines=12, max_chars=1800)
        raise
    finally:
        waiting.close()
        _call.reset(token)

"""Step 01: read the requirement tree, display every field, and analyze images."""

import json
import re
from pathlib import Path

import yaml

from infrastructure.shared.models.vision import VisualModel
from infrastructure.utils.presentation.console import DemoConsole
from infrastructure.utils.files import save_json, save_text
from infrastructure.stages.requirements.tree import RequirementTree
from infrastructure.shared.project.git import checkpoint


OSC8_OPEN = "\x1b]8;;"
OSC8_CLOSE = "\x1b]8;;\x1b\\"
ESC = "\x1b\\"


def description_text(value: object) -> str:
    """Return the human-readable description from either supported YAML shape."""
    if isinstance(value, dict):
        value = value.get("text", "")
    return value if isinstance(value, str) else ""


def preorder_nodes(root: dict):
    """Yield raw requirement nodes in document-order preorder."""
    yield root
    for child in root.get("children", []) or []:
        yield from preorder_nodes(child)


def terminal_link(label: str, target: Path) -> str:
    """Render an OSC 8 hyperlink understood by modern terminal emulators."""
    return f"{OSC8_OPEN}{target.resolve().as_uri()}{ESC}{label}{OSC8_CLOSE}"


class RequirementExplorer:
    """Show one requirement at a time with optional scenario and step expansion."""

    def __init__(self, input_path: Path, root: dict) -> None:
        self.input_path = input_path.resolve()
        self.input_dir = self.input_path.parent
        self.tree = RequirementTree(root)
        self.nodes = list(preorder_nodes(root))
        self.console = DemoConsole()
        self.images = self._collect_images(root)

    def _collect_images(self, root: dict) -> dict[str, dict]:
        images = {}
        for node in self.nodes:
            description = node.get("description", {})
            if not isinstance(description, dict):
                continue
            refs = description.get("image", [])
            if not isinstance(refs, list):
                continue
            for image in refs:
                if isinstance(image, dict) and isinstance(image.get("id"), str):
                    images[image["id"]] = image
        return images

    def _image_target(self, reference: object) -> tuple[str, Path | None, str | None]:
        """Resolve a requirement image while keeping file links inside input/."""
        if not isinstance(reference, str) or not reference.strip():
            return "(invalid image reference)", None, None
        source = Path(reference)
        target = source.resolve() if source.is_absolute() else (self.input_dir / source).resolve()
        if target != self.input_dir and self.input_dir not in target.parents:
            return reference, None, "outside input directory"
        if not target.is_file():
            return reference, target, "file not found"
        return reference, target, None

    def _references(self, references: object) -> list[tuple[str, Path | None, str | None]]:
        """Turn image IDs, reference macros, or direct image paths into link rows."""
        if not isinstance(references, list):
            return []
        result = []
        seen = set()
        for reference in references:
            if not isinstance(reference, str):
                continue
            match = re.search(r"ref\[image\]\(([^)]+)\)", reference, re.IGNORECASE)
            image_id = match.group(1) if match else reference
            image = self.images.get(image_id)
            raw_path = image.get("reference") if image else None
            if raw_path is None and Path(reference).suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"}:
                raw_path = reference
            if raw_path is None:
                continue
            label = image_id if image else Path(str(raw_path)).name
            display_path, target, problem = self._image_target(raw_path)
            key = (label, str(target) if target else display_path)
            if key not in seen:
                result.append((f"{label}  ·  {display_path}", target, problem))
                seen.add(key)
        return result

    @staticmethod
    def _requirement_images(node: dict) -> list:
        description = node.get("description", {})
        return description.get("image", []) if isinstance(description, dict) else []

    def _print_links(self, rows: list[tuple[str, Path | None, str | None]]) -> None:
        for label, target, problem in rows:
            if target is not None and problem is None:
                print(f"  ↗ {terminal_link(label, target)}")
            else:
                suffix = f"  [{problem}]" if problem else ""
                print(f"  ↗ {label}{suffix}")

    def _show_node(self, node: dict, index: int, expanded: bool) -> None:
        rid = node["id"]
        requirement = self.tree.requirements[rid]
        depth = self._depth(rid)
        own_steps = self.tree.own_steps[rid]
        scenario_count = len(node.get("scenarios", []) or [])
        children = self.tree.children[rid]
        indent = "  " * depth
        body = [
            f"Preorder node {index + 1}/{len(self.nodes)}   ·   Depth {depth}",
            f"Requirement: {indent}{rid}  |  {requirement['name']}",
            "",
            "Description:",
            description_text(node.get("description", "")) or "(No description.)",
            "",
            f"Scenarios: {scenario_count}   ·   Steps: {len(own_steps)}   ·   Children: {len(children)}",
            "Child requirements: " + (", ".join(children) if children else "(none)"),
        ]
        self.console.show(f"Requirement | {rid} — {requirement['name']}", "\n".join(body))

        images = []
        for image in self._requirement_images(node):
            if isinstance(image, dict):
                label = image.get("id", "reference image")
                display_path, target, problem = self._image_target(image.get("reference"))
                images.append((f"{label}  ·  {display_path}", target, problem))
        if images:
            print("Reference images (click to open):")
            self._print_links(images)
        elif not expanded:
            print("Reference images: (none)")

        if expanded:
            self._show_scenarios(node)

    def _show_scenarios(self, node: dict) -> None:
        scenarios = node.get("scenarios", []) or []
        if not scenarios:
            self.console.show("Scenarios and steps", "This requirement has no scenarios or steps.")
            return
        for scenario in scenarios:
            sid = scenario.get("id", "Scenario")
            lines = [f"Scenario: {sid}  |  {scenario.get('name', '')}"]
            steps = scenario.get("steps", []) or []
            if not steps:
                lines.append("(No steps.)")
            for step in steps:
                lines.extend([
                    "",
                    f"Step: {step.get('id', '(no id)')}",
                    f"Given: {step.get('Given', step.get('given', ''))}",
                    f"When:  {step.get('When', step.get('when', ''))}",
                    f"Then:  {step.get('Then', step.get('then', ''))}",
                ])
                references = self._references(step.get("references", []))
                if references:
                    lines.append("Image references: " + ", ".join(row[0].split("  ·  ")[0] for row in references))
            self.console.show(f"Scenario | {sid}", "\n".join(lines))
            for step in steps:
                self._print_links(self._references(step.get("references", [])))

    def _depth(self, requirement_id: str) -> int:
        """Find a node's depth from the already-normalized containment tree."""
        def search(current: str, depth: int):
            if current == requirement_id:
                return depth
            for child in self.tree.children[current]:
                found = search(child, depth + 1)
                if found is not None:
                    return found
            return None

        return search(next(iter(self.tree.requirements)), 0) or 0

    def run(self) -> None:
        index = 0
        expanded = False
        while 0 <= index < len(self.nodes):
            self._show_node(self.nodes[index], index, expanded)
            prompt = "[Enter/n] next  [p] previous  [e] expand scenarios/steps  [c] collapse  [q] quit > "
            try:
                command = input(prompt).strip().lower()
            except EOFError:
                print()
                break
            if command in {"", "n", "next"}:
                index += 1
                expanded = False
            elif command in {"p", "prev", "previous"}:
                index = max(0, index - 1)
                expanded = False
            elif command in {"e", "expand"}:
                expanded = True
            elif command in {"c", "collapse"}:
                expanded = False
            elif command in {"q", "quit", "x"}:
                break
            else:
                print("Use Enter/n, p, e, c, or q.")
        print("Requirement browsing ended.")


def load_requirements(path: Path) -> dict:
    """Load YAML and validate its requirement/scenario/step IDs."""
    if not path.is_file():
        raise ValueError(f"Requirements file not found: {path}")
    try:
        root = yaml.safe_load(path.read_text(encoding="utf-8-sig"))
    except yaml.YAMLError as error:
        raise ValueError(f"Invalid requirements.yaml: {error}") from error
    if not isinstance(root, dict):
        raise ValueError("The requirements YAML root must be an object")
    RequirementTree(root)
    return root


def collect_images(value: object) -> list[str]:
    """Collect description.image references recursively in first-seen order."""
    references = []
    if isinstance(value, dict):
        description = value.get("description")
        if isinstance(description, dict):
            images = description.get("image", [])
            if not isinstance(images, list):
                raise ValueError("description.image must be a list")
            for image in images:
                if not isinstance(image, dict) or not isinstance(image.get("reference"), str):
                    raise ValueError("Each image must have a string reference")
                if not image["reference"].strip():
                    raise ValueError("Image reference must not be empty")
                references.append(image["reference"])
        for child in value.values():
            references.extend(collect_images(child))
    elif isinstance(value, list):
        for child in value:
            references.extend(collect_images(child))
    return list(dict.fromkeys(references))


def explore_requirement(input_dir: Path, arc_dir: Path, pause: bool = False) -> dict:
    console = DemoConsole(pause)
    # --- Extension point 01A: requirement parsing -----------------------------
    # Try another source format or stronger syntax checks here. Preserve IDs,
    # containment, scenarios, and step text: later passes depend on these links.
    source = input_dir / "requirements.yaml"
    try:
        requirements = yaml.safe_load(source.read_text(encoding="utf-8-sig"))
    except yaml.YAMLError as error:
        raise ValueError(f"Invalid requirements.yaml: {error}") from error
    if not isinstance(requirements, dict):
        raise ValueError("The root of requirements.yaml must be a requirement object")
    try:
        text = json.dumps(requirements, ensure_ascii=False, indent=2, allow_nan=False)
    except (TypeError, ValueError) as error:
        raise ValueError(f"Cannot convert requirement fields to JSON: {error}") from error
    console.artifact("requirements", requirements, "1. Requirement tree")

    # --- Extension point 01B: reference discovery ------------------------------
    # collect_images() defines which references count as visual evidence.
    # Extend discovery for other document formats; keep paths input-relative.
    references = collect_images(requirements)
    for reference in references:
        image = (input_dir / reference).resolve()
        if not image.is_relative_to(input_dir.resolve()):
            raise ValueError(f"Referenced image must be inside the input directory: {reference}")
        if not image.is_file():
            raise ValueError(f"Referenced image does not exist: {reference}")
    console.show("2. Referenced images", "\n".join(references) or "(No referenced images.)")

    # --- Extension point 01C: visual analysis ----------------------------------
    # Rewrite the prompt/model in infrastructure/shared/models/vision.py to compare
    # visual extraction strategies. Keep {layout, elements, style}, or update
    # the response validator and downstream consumers together.
    arc_dir.mkdir(parents=True, exist_ok=True)
    save_text(arc_dir / "requirements.json", text + "\n")
    checkpoint(arc_dir.parent, stage="01", task="requirements", action="Publish input requirement snapshot",
        details={"source": str(source), "image_references": references})
    analysis = {}
    if references:
        model = VisualModel()
        for reference in references:
            print(f"Analyzing image: {reference}", flush=True)
            analysis[reference] = model.analyze(input_dir / reference)
            save_json(arc_dir / "visual_analysis.json", analysis)
            checkpoint(arc_dir.parent, stage="01", task=reference, action="Publish visual reference analysis",
                details={"reference": reference, "analysis": analysis[reference]})
            console.show(f"3. Visual analysis | {reference}", json.dumps(analysis[reference], ensure_ascii=False, indent=2))
    else:
        console.show("3. Visual analysis", "No referenced images; no model call is needed.")
    save_json(arc_dir / "visual_analysis.json", analysis)
    print(f"Results saved: {arc_dir / 'requirements.json'}, {arc_dir / 'visual_analysis.json'}")
    return requirements

import type { Express } from "express";
import type Database from "better-sqlite3";

// API implementation tasks maintain this registry and preserve existing routes.
export function registerApis(_app: Express, _connection: Database.Database): void {}
// Each invocation owns its backend process, port and temporary database.
import { mkdtempSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createServer } from "node:net";
import { spawn } from "node:child_process";
import { setTimeout as delay } from "node:timers/promises";

const root = fileURLToPath(new URL("../../", import.meta.url));
function discover(directory) {
  return readdirSync(directory, { withFileTypes: true }).flatMap(entry => {
    const path = join(directory, entry.name);
    return entry.isDirectory() ? discover(path) : path.endsWith(".test.ts") ? [path] : [];
  });
}
async function freePort() {
  const listener = createServer();
  await new Promise((resolve, reject) => {
    listener.once("error", reject);
    listener.listen(0, "127.0.0.1", resolve);
  });
  const port = listener.address().port;
  await new Promise((resolve, reject) => listener.close(error => error ? reject(error) : resolve()));
  return port;
}
async function stop(child) {
  if (!child?.pid || child.exitCode !== null || child.signalCode !== null) return;
  const exited = new Promise(resolve => child.once("exit", resolve));
  child.kill("SIGTERM");
  await Promise.race([exited, delay(3000, undefined, { ref: false })]);
  if (child.exitCode === null && child.signalCode === null) {
    child.kill("SIGKILL");
    await exited;
  }
}

let backend, tests, directory, interrupted = false;
let backendOutput = "", backendError;
let phase = "runner";
const interrupt = () => {
  interrupted = true;
  void stop(tests);
  void stop(backend);
};
process.on("SIGINT", interrupt);
process.on("SIGTERM", interrupt);
try {
  const requested = process.argv.slice(2);
  const files = requested.length ? requested.map(path => resolve(root, path))
    : discover(join(root, "backend/tests")).sort();
  if (!files.length) throw new Error("No API tests found; run step 08 first.");
  directory = mkdtempSync(join(tmpdir(), "arc-api-"));
  const port = await freePort();
  const baseURL = `http://127.0.0.1:${port}`;
  const database = join(directory, "app.db");
  const env = { ...process.env, PORT: String(port), DATABASE_URL: database,
    ARC_API_BASE_URL: baseURL, ARC_API_DB_FILE: database };
  phase = "startup";
  backend = spawn(process.execPath, ["--import", "tsx", "backend/src/server.ts"], {
    cwd: root, env, stdio: ["ignore", "pipe", "pipe"],
  });
  const record = data => { backendOutput = (backendOutput + data).slice(-12000); };
  backend.stdout.on("data", record);
  backend.stderr.on("data", record);
  backend.on("error", error => { backendError = error; });
  let ready = false;
  const deadline = Date.now() + 30000;
  while (Date.now() < deadline) {
    if (interrupted) throw new Error("Backend HTTP checks interrupted");
    if (backendError) throw backendError;
    if (backend.exitCode !== null || backend.signalCode !== null)
      throw new Error("Backend exited before readiness");
    const response = await fetch(`${baseURL}/api/health`, {
      signal: AbortSignal.timeout(1000),
    }).catch(() => null);
    if (response?.ok) { await response.arrayBuffer(); ready = true; break; }
    if (response) await response.arrayBuffer();
    await delay(100);
  }
  if (!ready) throw new Error("Backend did not become ready within 30 seconds");
  phase = "tests";
  tests = spawn(process.execPath, ["--import", "tsx", "--test", "--test-concurrency=1",
    "--test-reporter=tap", ...files], { cwd: root, env, stdio: "inherit" });
  const code = await new Promise((resolve, reject) => {
    tests.once("error", reject);
    tests.once("close", code => resolve(code ?? 1));
  });
  if (interrupted) throw new Error("Backend HTTP checks interrupted");
  if (backend.exitCode !== null || backend.signalCode !== null)
    throw new Error("Backend exited during HTTP tests");
  process.exitCode = code;
  if (code && backendOutput) console.error("BACKEND_LOG:\n" + backendOutput);
} catch (error) {
  const tag = phase === "startup" ? "BACKEND_STARTUP_ERROR"
    : phase === "tests" ? "BACKEND_RUNTIME_ERROR" : "BACKEND_RUNNER_ERROR";
  console.error(`${tag}: ${error.stack ?? String(error)}\n${backendOutput}`);
  process.exitCode = 1;
} finally {
  await stop(tests);
  await stop(backend);
  process.off("SIGINT", interrupt);
  process.off("SIGTERM", interrupt);
  if (directory) rmSync(directory, { recursive: true, force: true, maxRetries: 20, retryDelay: 100 });
}

"""Bounded, on-demand access to compiler-owned global state."""

import json
from copy import deepcopy

from infrastructure.shared.agent.files import source_paths
from infrastructure.shared.rag.bm25 import tokenize
from infrastructure.utils.files import read_artifact

DISCOVERY_RULES = '''Context contains selected excerpts, never a complete global inventory.
Use the supplied task records first. Query only a specific missing fact needed for the
current decision; do not search to reconfirm definitions already supplied or retained.
When evidence is missing, return only {"context_request": {"kind": "schema",
"query": "session credential"}} to discover candidates, or use "ids": ["Account.id"]
to read exact records. Available kinds are listed in context_kinds.
context_request is an ordinary JSON field, NOT a native tool. Never serialize it as
DSML, XML, invoke/parameter tags or a provider tool-call block. For example, when page
is an advertised kind, search shelves by returning exactly:
{"context_request":{"kind":"page","query":"shelves"}}
Do not put this object inside tags, Markdown or a JSON string.
Only those advertised kinds are supported; examples below do not enable other scopes.
Search returns IDs/descriptions, not definitions, except requirement searches return complete records.
Read needed IDs before modifying or calling other kinds of records.
Each query searches only its named kind; do not search unrelated collections for context.
Use offset to inspect another search page. A miss is not proof of absence. Search
shared concepts before creating new entities/APIs; reuse canonical definitions.
For schema, read Entity.field for a narrow field definition; for large pages read
ui_element IDs. kind=file supports exact relative paths or keyword discovery.
For a file excerpt, supply "start_line": 10 and "end_line": 40 alongside ids.
Lines are 1-based and inclusive; end_line may be omitted to read through EOF.
Excerpts return content, start_line, end_line and total_lines. File-writing agents use
read_file instead of kind=file exact reads; semantic design tasks may use these excerpts.
kind=requirement reads original requirement scenarios; kind=test_requirement with a
test file path as an ID finds its original requirement owner IDs. Read the relevant requirement before
changing a regression test; never infer its intended behavior from implementation.
Exact records are retained in context_records and search candidates in context_candidates
for the current task. File-editing tasks
also retain read_file excerpts in read_files. Use retained evidence instead of querying
it again. Return your normal stage output when enough evidence is available.
There is no fixed query-count or character cap. Prefer exact reads after candidate
searches. Do not repeat searches returning the same candidates: read their IDs, or
produce the stage output using the available evidence. Query errors are feedback,
not evidence that an object is absent.'''


class DiscoveryStalled(ValueError):
    """Repeated identical results need a proposal or different evidence, not more searches."""


class DiscoverySession:
    """Allow as many useful queries as needed; return malformed queries as feedback."""

    def __init__(self, index):
        self.index = index
        self.results = {}
        self.evidence = {}
        self.candidates = {}

    def resolve(self, query):
        try:
            result = self.index.query(query)
        except (ValueError, KeyError, TypeError, AttributeError, IndexError) as error:
            raise ValueError(f'Invalid context_request {query!r}: {error}. '
                f'Available kinds: {list(self.index.records())}. '
                'Correct the query or return the normal stage output.') from error
        kind = result.get('kind')
        for candidate in result.get('candidates', []):
            if candidate['id'] not in self.evidence.get(kind, {}):
                self.candidates.setdefault(kind, {})[candidate['id']] = deepcopy(candidate)
        if result.get('records'):
            self.evidence.setdefault(kind, {}).update(deepcopy(result['records']))
            for identity in result['records']:
                self.candidates.get(kind, {}).pop(identity, None)
        return self.observe(result)

    def observe(self, result):
        """Apply the same no-progress feedback to semantic queries and file reads."""
        fingerprint = json.dumps(result, sort_keys=True, ensure_ascii=False)
        count = self.results.get(fingerprint, 0) + 1
        self.results[fingerprint] = count
        if count >= 3:
            raise DiscoveryStalled('Discovery returned the same evidence repeatedly. '
                'Read different relevant evidence or return the task output.')
        if count == 2:
            result = {**result, 'next_action': 'These results were already supplied. '
                'Read different evidence or produce the task output.'}
        return result



class ContextIndex:
    """Keep complete collections in the host; expose small candidate pages and exact reads."""
    def __init__(self, collections, output=None):
        self.collections = collections
        self.output = output

    def records(self):
        return self.collections() if callable(self.collections) else self.collections

    def query(self, request):
        collections = self.records()
        kind = request['kind']
        records = collections[kind]
        ids = request.get('ids')
        ranged = 'start_line' in request or 'end_line' in request
        if ranged:
            if kind != 'file' or ids is None:
                raise ValueError('Line ranges require kind=file and exact ids')
            start, end = request.get('start_line', 1), request.get('end_line')
            if type(start) is not int or start < 1 or ('end_line' in request and
                    (type(end) is not int or end < start)):
                raise ValueError('Line numbers must be positive integers with end_line >= start_line')
        if ids is not None:
            if not isinstance(ids, list) or any(not isinstance(identity, str) for identity in ids):
                raise ValueError('ids must be an array of strings')
            found = {}
            for identity in ids:
                if kind == 'file':
                    if identity not in records:
                        continue
                    path = self.output / identity
                    if path.is_symlink() or not path.resolve().is_relative_to(self.output.resolve()):
                        raise ValueError('File must be inside the project')
                    content = path.read_text(encoding='utf-8-sig')
                    if ranged:
                        lines = content.splitlines(keepends=True)
                        last = min(end if end is not None else len(lines), len(lines))
                        found[identity] = {'content': ''.join(lines[start - 1:last]),
                            'start_line': start, 'end_line': last, 'total_lines': len(lines)}
                    else:
                        found[identity] = content
                elif kind == 'schema' and '.' in identity:
                    entity, field = identity.split('.', 1)
                    if entity in records and field in records[entity]['fields']:
                        found[identity] = records[entity]['fields'][field]
                elif identity in records:
                    if kind == 'test_requirement':
                        offset = max(0, int(request.get('offset', 0)))
                        owners = records[identity]
                        found[identity] = {'requirement_ids': owners[offset:offset + 6],
                            'next_offset': offset + 6 if offset + 6 < len(owners) else None}
                    else:
                        found[identity] = records[identity]
            result = {'records': deepcopy(found), 'missing': [key for key in ids if key not in found]}
        else:
            words = set(tokenize(request['query']))
            if not words:
                raise ValueError('Provide a nonempty discovery query')
            scores = []
            for key, record in records.items():
                text = key + ' ' + json.dumps(record, ensure_ascii=False)
                score = len(words.intersection(tokenize(text)))
                if request['query'].lower() in text.lower():
                    score += 1
                if score:
                    scores.append((-score, key))
            scores.sort()
            offset = max(0, int(request.get('offset', 0)))
            candidates = []
            for _, key in scores[offset:offset + 6]:
                value = records[key]
                description = value.get('description', value.get('name', '')) if isinstance(value, dict) else ''
                candidates.append({'id': key, 'description': str(description)[:300]})
            result = {'candidates': candidates, 'next_offset': offset + 6 if offset + 6 < len(scores) else None,
                'notice': 'Lexical candidates only. A miss does not establish absence.'}
            if kind == 'requirement':
                result['records'] = {item['id']: deepcopy(records[item['id']]) for item in candidates}
                del result['candidates']
        return {'kind': kind, **result}


def project_index(output, *, kinds, file_roots=()):
    """Expose only stage-selected collections and source directories, rebuilt on demand."""
    from infrastructure.stages.requirements.tree import RequirementTree
    from infrastructure.stages.backend.context import requirement_context
    from infrastructure.stages.frontend.ui.design import owners, data_symbols

    def artifact(name, default):
        return read_artifact(output / '.arc', name) if (output / '.arc' / name).is_file() else default

    def records():
        result = {}
        backend_tests = 'test_requirement' in kinds and any(root.startswith('backend/') for root in file_roots)
        frontend_tests = 'test_requirement' in kinds and any(root.startswith('frontend/') for root in file_roots)
        if 'schema' in kinds:
            result['schema'] = artifact('db_schema.json', {'entities': {}})['entities']
        if 'api' in kinds or backend_tests:
            backend = artifact('backend_apis.json', {'apis': {}, 'requirements': {}})
            if 'api' in kinds:
                result['api'] = backend['apis']
        if any(kind in kinds for kind in ('page', 'ui_element', 'ui_data')) or frontend_tests:
            ui = artifact('ui_design.json', {'pages': {}, 'elements': {}, 'requirements': {}})
            if 'page' in kinds:
                result['page'] = ui['pages']
            if 'ui_element' in kinds:
                result['ui_element'] = ui['elements']
            if 'ui_data' in kinds:
                result['ui_data'] = data_symbols(ui['elements'])
        if 'trigger' in kinds:
            result['trigger'] = artifact('frontend_triggers.json', {'triggers': {}})['triggers']
        if 'convention' in kinds:
            result['convention'] = artifact('shared_conventions.json', {})
        if 'requirement' in kinds or 'test_requirement' in kinds:
            tree = RequirementTree(artifact('requirements.json', {'id': 'ROOT'}))
            requirements = {rid: requirement_context(tree, rid) for rid in tree.leaves}
            if 'requirement' in kinds:
                result['requirement'] = requirements
        if 'test_requirement' in kinds:
            paths = artifact('implementation_paths.json', {})
            test_owners = {}
            if backend_tests:
                for aid, path in paths.get('backend_test', {}).items():
                    test_owners[path] = [rid for rid, aids in backend['requirements'].items()
                        if aid in aids and rid in requirements]
            if frontend_tests:
                for rid, path in paths.get('e2e_test', {}).items():
                    test_owners[path] = [rid] if rid in requirements else []
                for pid in ui['pages']:
                    path = f'frontend/tests/ui/{pid}.spec.ts'
                    test_owners[path] = [rid for rid in owners(ui, pid) if rid in requirements]
            prefixes = tuple(root + '/' for root in file_roots)
            result['test_requirement'] = {path: ids for path, ids in test_owners.items()
                if path.startswith(prefixes)}
        if 'file' in kinds:
            result['file'] = {path: {} for root in file_roots for path in source_paths(output, root)}
        return result

    return ContextIndex(records, output)
